class Solution {
    public int[] xorQueries(int[] arr,int[][] queries){
        int[] prefix=new int[arr.length+1];
        for(int i=0;i<arr.length;i++)prefix[i+1]=prefix[i]^arr[i];
        int[] answer=new int[queries.length];
        for(int i=0;i<queries.length;i++)answer[i]=prefix[queries[i][1]+1]^prefix[queries[i][0]];
        return answer;
    }
}

code.kotlin:
class Solution {
    fun xorQueries(arr:IntArray,queries:Array<IntArray>):IntArray{
        val prefix=IntArray(arr.size+1);
        for(i in arr.indices)prefix[i+1]=prefix[i] xor arr[i];
        return IntArray(queries.size){
            prefix[queries[it][1]+1] xor prefix[queries[it][0]]
        }
    }
}

code.cpp:
class Solution {
    public: vector<int> xorQueries(vector<int>& arr,vector<vector<int>>& queries){
        vector<int> prefix(arr.size()+1);
        for(int i=0;i<(int)arr.size();++i)prefix[i+1]=prefix[i]^arr[i];
        vector<int> answer;
        for(auto& query:queries)answer.push_back(prefix[query[1]+1]^prefix[query[0]]);
        return answer;
    }
};
